text:
도장 사용법




대응 이론: Ch03 딥러닝의 학습 (후반: 미분 → 경사하강법 → 2차원 확장)
학번을 입력하면 나만의 문제가 나옵니다. 새 문제 버튼으로 무한 반복 연습.
이 주차는 계산기가 필요합니다. 지수 e^x 와 자연로그 ln 을 쓰는 문제가 있습니다.
유형은 3개 — [응용] 1 → [도전] 2.
훈련 기준: 각 유형에서 연속 3문제 무실수.
// mulberry32 — 문제 번호(시드)가 같으면 항상 같은 문제가 생성된다
dojoRng = function (seed) {
  let a = (seed * 7919 + 104729) &gt;&gt;&gt; 0;
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a &gt;&gt;&gt; 15), 1 | a);
    t = (t + Math.imul(t ^ (t &gt;&gt;&gt; 7), 61 | t)) ^ t;
    return ((t ^ (t &gt;&gt;&gt; 14)) &gt;&gt;&gt; 0) / 4294967296;
  };
}
dojoInt = (rng, lo, hi) =&gt; lo + Math.floor(rng() * (hi - lo + 1))
dojoPick = (rng, arr) =&gt; arr[Math.floor(rng() * arr.length)]
// 정답 비교 — tol 이내면 정답 처리 (학생의 반올림 오차 허용)
dojoOk = (user, answer, tol = 0.005) =&gt;
  user !== null && user !== undefined && Number.isFinite(user) && Math.abs(user - answer) &lt;= tol
dojoMark = (label, ok, answerShown) =&gt; `
  &lt;div style="display:flex;align-items:center;gap:0.5em;padding:0.25em 0;"&gt;
    &lt;span style="font-size:1.1em;"&gt;${ok ? "✅" : "❌"}&lt;/span&gt;
    &lt;span style="font-weight:600;"&gt;${label}&lt;/span&gt;
    &lt;span style="color:${ok ? "#2E7D32" : "#8C1515"};"&gt;
      ${ok ? "정답" : (answerShown != null ? "오답 — 다시 계산해 보세요" : "오답")}
    &lt;/span&gt;
  &lt;/div&gt;`
// 문제 카드
dojoProblem = (title, bodyHtml) =&gt; html`
  &lt;div style="font-family:'Pretendard',sans-serif;border:1.5px solid #8C1515;border-radius:8px;
    overflow:hidden;margin:0.6em 0;max-width:720px;"&gt;
    &lt;div style="background:#8C1515;color:white;padding:0.4em 0.9em;font-weight:700;font-size:0.95em;"&gt;
      ${title}
    &lt;/div&gt;
    &lt;div style="padding:0.7em 0.9em;line-height:1.9;font-size:0.95em;"&gt;${bodyHtml}&lt;/div&gt;
  &lt;/div&gt;`
// 채점 결과 카드
dojoResult = (marks, allOk) =&gt; html`
  &lt;div style="font-family:'Pretendard',sans-serif;border-radius:8px;max-width:720px;margin:0.4em 0;
    padding:0.6em 0.9em;font-size:0.92em;
    background:${allOk ? "#E8F5E9" : "#FFF8E1"};
    border:1.5px solid ${allOk ? "#2E7D32" : "#D4A017"};"&gt;
    ${marks.join("")}
    &lt;div style="margin-top:0.35em;font-weight:700;color:${allOk ? "#2E7D32" : "#B8860B"};"&gt;
      ${allOk ? "🎉 전부 정답! 문제 번호를 바꿔 한 번 더 연습해 보세요." : "빨간 항목을 다시 풀어 보세요. 막히면 풀이 보기를 켜세요."}
    &lt;/div&gt;
  &lt;/div&gt;`
// 풀이 카드
dojoSolution = (stepsHtml) =&gt; html`
  &lt;div style="font-family:'Pretendard',sans-serif;border-radius:8px;max-width:720px;margin:0.4em 0;
    padding:0.7em 0.9em;background:#E3F2FD;border:1.5px solid #1565C0;
    line-height:2.0;font-size:0.92em;"&gt;
    &lt;div style="font-weight:700;color:#1565C0;margin-bottom:0.2em;"&gt;풀이&lt;/div&gt;
    ${stepsHtml}
  &lt;/div&gt;`
// FNV-1a — 학번 문자열을 정수로. 사람마다 다른 문제가 나오게 하는 출발점.
dojoHash = function (str) {
  let h = 2166136261 &gt;&gt;&gt; 0;
  const s = String(str);
  for (let i = 0; i &lt; s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 16777619) &gt;&gt;&gt; 0;
  }
  return h &gt;&gt;&gt; 0;
}
// (학번, 주차, 유형, 라운드) → 문제 번호.
// 학번이 다르면 다른 문제, 같은 학번·같은 라운드면 항상 같은 문제(재현 가능).
dojoSeed = function (sid, week, type, round) {
  const key = (sid && String(sid).trim()) ? String(sid).trim() : "guest";
  return (dojoHash(key + "|" + week + "|" + type + "|" + round) % 99999) + 1;
}
// 학번 입력 — 브라우저에 저장되어 모든 도장 페이지에서 유지된다.
viewof dojoSid = Inputs.text({
  label: "학번",
  placeholder: "예: 202312345",
  value: (() =&gt; { try { return localStorage.getItem("dojoSid") || ""; } catch (e) { return ""; } })(),
  width: 260
})
{
  try { localStorage.setItem("dojoSid", dojoSid || ""); } catch (e) {}
  const named = dojoSid && dojoSid.trim();
  return html`&lt;div style="font-family:'Pretendard',sans-serif;font-size:0.85em;
    padding:0.45em 0.8em;border-radius:6px;max-width:720px;margin:0.1em 0 0.9em;
    background:${named ? "#E8F5E9" : "#FFF8E1"};
    border:1px solid ${named ? "#A5D6A7" : "#E8D9A0"};color:${named ? "#2E7D32" : "#8A6D1B"};"&gt;
    ${named
      ? `학번 &lt;strong&gt;${dojoSid.trim()}&lt;/strong&gt; 기준으로 문제가 생성됩니다 — 옆 사람과 다른 문제가 나옵니다.`
      : `학번을 입력하면 &lt;strong&gt;나만의 문제 세트&lt;/strong&gt;가 만들어집니다. (비워 두면 공용 연습 문제)`}
  &lt;/div&gt;`;
}
// "새 문제" 버튼 + 문제 코드 표시를 한 줄로 묶는 헤더
dojoBar = (code) =&gt; html`
  &lt;div style="font-family:'Pretendard',sans-serif;font-size:0.82em;color:#666;
    margin:-0.3em 0 0.5em;"&gt;
    문제 코드 &lt;code style="background:#F1F3F5;padding:0.1em 0.4em;border-radius:4px;
    color:#8C1515;font-weight:700;"&gt;${code}&lt;/code&gt;
    &lt;span style="color:#999;"&gt; — 질문할 때 이 코드를 알려주세요&lt;/span&gt;
  &lt;/div&gt;`

유형 A — 경사하강 1스텝 [응용]

viewof rE_round = Inputs.button("새 문제", { value: 0, reduce: (v) =&gt; v + 1 })







rE_seed = dojoSeed(dojoSid, 3, "E", rE_round)







rE = {
  const rng = dojoRng(rE_seed);
  const a = dojoInt(rng, 1, 8);
  const th = dojoInt(rng, -6, 12);
  const eta = dojoPick(rng, [0.05, 0.1, 0.2, 0.25, 0.5]);
  const g = 2 * (th - a);
  const nt = Math.round((th - eta * g) * 10000) / 10000;
  return { a, th, eta, g, nt, l0: Math.pow(th - a, 2), l1: Math.round(Math.pow(nt - a, 2) * 10000) / 10000 };
}







dojoBar(`E-${rE_seed}`)







dojoProblem(`문제 E — 경사하강 1스텝`, `
  손실 함수가 &lt;strong&gt;L(θ) = (θ − ${rE.a})²&lt;/strong&gt; 이고,
  현재 파라미터는 &lt;strong&gt;θ = ${rE.th}&lt;/strong&gt;, 학습률은 &lt;strong&gt;η = ${rE.eta}&lt;/strong&gt; 이다.&lt;br&gt;
  ① 현재 위치의 기울기 &lt;strong&gt;dL/dθ&lt;/strong&gt;,
  ② 1스텝 갱신 후의 &lt;strong&gt;θ&lt;sub&gt;new&lt;/sub&gt;&lt;/strong&gt; 를 구하라.
  &lt;div style="margin-top:0.4em;color:#666;font-size:0.92em;"&gt;
  갱신식: θ&lt;sub&gt;new&lt;/sub&gt; = θ − η · (dL/dθ)
  &lt;/div&gt;`)







viewof rE_ans_g = Inputs.number({ label: "dL/dθ =", step: 0.01 })
viewof rE_ans_t = Inputs.number({ label: "θ_new =", step: 0.0001 })
viewof rE_grade = Inputs.toggle({ label: "채점", value: false })
viewof rE_show = Inputs.toggle({ label: "풀이 보기", value: false })






























rE_grade ? dojoResult(
  [dojoMark("기울기", dojoOk(rE_ans_g, rE.g, 0.011)),
   dojoMark("θ_new", dojoOk(rE_ans_t, rE.nt, 0.0015))],
  dojoOk(rE_ans_g, rE.g, 0.011) && dojoOk(rE_ans_t, rE.nt, 0.0015)
) : html``







rE_show ? dojoSolution(`
  ① L(θ) = (θ − ${rE.a})² 의 도함수는 dL/dθ = 2(θ − ${rE.a}).&lt;br&gt;
  &nbsp;&nbsp;θ = ${rE.th} 을 대입: 2 × (${rE.th} − ${rE.a}) = 2 × ${rE.th - rE.a}
  = &lt;strong&gt;${rE.g}&lt;/strong&gt;&lt;br&gt;
  ② θ&lt;sub&gt;new&lt;/sub&gt; = ${rE.th} − ${rE.eta} × (${rE.g}) = ${rE.th} − ${(rE.eta * rE.g).toFixed(4)}
  = &lt;strong&gt;${rE.nt}&lt;/strong&gt;&lt;br&gt;
  검산: 손실이 ${rE.l0} → ${rE.l1} 로 ${rE.l1 &lt; rE.l0 ? "줄었다 ✅" : "줄지 않았다 — 학습률이 너무 크다"}&lt;br&gt;
  &lt;span style="color:#555;"&gt;기울기가 ${rE.g &gt; 0 ? "양수이므로 θ를 &lt;strong&gt;줄이는&lt;/strong&gt;" : "음수이므로 θ를 &lt;strong&gt;키우는&lt;/strong&gt;"}
  방향으로 움직인다. 그래서 갱신식에 &lt;strong&gt;마이너스&lt;/strong&gt;가 붙는다.&lt;/span&gt;`) : html``

유형 B — 퍼셉트론 파라미터의 경사하강 1스텝 [도전]

viewof rF_round = Inputs.button("새 문제", { value: 0, reduce: (v) =&gt; v + 1 })







rF_seed = dojoSeed(dojoSid, 3, "F", rF_round)







rF = {
  const rng = dojoRng(rF_seed);
  const w = dojoInt(rng, -20, 20) / 10;
  const b = dojoInt(rng, -20, 20) / 10;
  const x = dojoInt(rng, 1, 5);
  const y = dojoInt(rng, -10, 30) / 10;
  const eta = dojoPick(rng, [0.01, 0.02, 0.05, 0.1]);
  const yh = Math.round((w * x + b) * 10000) / 10000;
  const r = Math.round((y - yh) * 10000) / 10000;
  const gw = Math.round(-2 * r * x * 10000) / 10000;
  const gb = Math.round(-2 * r * 10000) / 10000;
  return {
    w, b, x, y, eta, yh, r, gw, gb,
    nw: Math.round((w - eta * gw) * 10000) / 10000,
    nb: Math.round((b - eta * gb) * 10000) / 10000
  };
}







dojoBar(`F-${rF_seed}`)







dojoProblem(`문제 F — 파라미터 갱신 1스텝`, `
  퍼셉트론 &lt;strong&gt;ŷ = w·x + b&lt;/strong&gt; (활성화는 항등함수)의 현재 파라미터가
  &lt;strong&gt;w = ${rF.w}, b = ${rF.b}&lt;/strong&gt; 이다.
  데이터 한 건 &lt;strong&gt;(x = ${rF.x}, y = ${rF.y})&lt;/strong&gt; 로 학습한다.
  손실은 &lt;strong&gt;L = (y − ŷ)²&lt;/strong&gt;, 학습률은 &lt;strong&gt;η = ${rF.eta}&lt;/strong&gt;.
  &lt;div style="margin:0.5em 0;padding:0.5em 0.8em;background:#F8F9FA;border-radius:6px;"&gt;
  그래디언트 공식: &nbsp; ∂L/∂w = −2(y − ŷ)·x &nbsp;&nbsp;|&nbsp;&nbsp; ∂L/∂b = −2(y − ŷ)
  &lt;/div&gt;
  ① 예측값 ŷ, ② ∂L/∂w, ③ 갱신 후 w&lt;sub&gt;new&lt;/sub&gt; 를 구하라. (소수 셋째 자리까지)`)







viewof rF_ans_yh = Inputs.number({ label: "ŷ =", step: 0.001 })
viewof rF_ans_gw = Inputs.number({ label: "∂L/∂w =", step: 0.001 })
viewof rF_ans_nw = Inputs.number({ label: "w_new =", step: 0.001 })
viewof rF_grade = Inputs.toggle({ label: "채점", value: false })
viewof rF_show = Inputs.toggle({ label: "풀이 보기", value: false })





































rF_grade ? dojoResult(
  [dojoMark("예측값 ŷ", dojoOk(rF_ans_yh, rF.yh, 0.0015)),
   dojoMark("∂L/∂w", dojoOk(rF_ans_gw, rF.gw, 0.0025)),
   dojoMark("w_new", dojoOk(rF_ans_nw, rF.nw, 0.0025))],
  dojoOk(rF_ans_yh, rF.yh, 0.0015) && dojoOk(rF_ans_gw, rF.gw, 0.0025) && dojoOk(rF_ans_nw, rF.nw, 0.0025)
) : html``







rF_show ? dojoSolution(`
  ① &lt;strong&gt;순전파&lt;/strong&gt;: ŷ = ${rF.w} × ${rF.x} + ${rF.b} = &lt;strong&gt;${rF.yh}&lt;/strong&gt;&lt;br&gt;
  ② &lt;strong&gt;오차&lt;/strong&gt;: y − ŷ = ${rF.y} − ${rF.yh} = ${rF.r}&lt;br&gt;
  &nbsp;&nbsp;∂L/∂w = −2 × (${rF.r}) × ${rF.x} = &lt;strong&gt;${rF.gw}&lt;/strong&gt;&lt;br&gt;
  &nbsp;&nbsp;(참고: ∂L/∂b = −2 × (${rF.r}) = ${rF.gb})&lt;br&gt;
  ③ &lt;strong&gt;갱신&lt;/strong&gt;: w&lt;sub&gt;new&lt;/sub&gt; = ${rF.w} − ${rF.eta} × (${rF.gw})
  = &lt;strong&gt;${rF.nw}&lt;/strong&gt; &nbsp;(b&lt;sub&gt;new&lt;/sub&gt; = ${rF.nb})&lt;br&gt;
  &lt;span style="color:#555;"&gt;순전파 → 손실 → 그래디언트 → 갱신. 이 네 단계가 학습 1스텝의 전부다.
  ∂L/∂w 공식이 &lt;strong&gt;어디서 오는지&lt;/strong&gt;는 Ch04의 연쇄법칙에서 직접 유도한다.&lt;/span&gt;`) : html``

유형 C — 학습률과 수렴 판정 [도전]

viewof rH_round = Inputs.button("새 문제", { value: 0, reduce: (v) =&gt; v + 1 })







rH_seed = dojoSeed(dojoSid, 3, "H", rH_round)







rH = {
  const rng = dojoRng(rH_seed);
  const a = dojoInt(rng, 1, 6);
  const th0 = a + dojoPick(rng, [-4, -3, -2, 2, 3, 4]);
  const eta = dojoPick(rng, [0.1, 0.25, 0.5, 0.8, 1.0, 1.2]);
  const step = (t) =&gt; Math.round((t - eta * 2 * (t - a)) * 100000) / 100000;
  const t1 = step(th0), t2 = step(t1);
  const factor = Math.abs(1 - 2 * eta);
  return {
    a, th0, eta, t1, t2, factor,
    verdict: factor &lt; 1 ? "수렴" : (factor &gt; 1 ? "발산" : "진동(제자리)"),
    d0: Math.abs(th0 - a), d2: Math.round(Math.abs(t2 - a) * 100000) / 100000
  };
}







dojoBar(`H-${rH_seed}`)







dojoProblem(`문제 H — 두 스텝과 수렴 판정`, `
  손실 함수 &lt;strong&gt;L(θ) = (θ − ${rH.a})²&lt;/strong&gt;, 초기값
  &lt;strong&gt;θ₀ = ${rH.th0}&lt;/strong&gt;, 학습률 &lt;strong&gt;η = ${rH.eta}&lt;/strong&gt; 이다.&lt;br&gt;
  ① 경사하강을 &lt;strong&gt;2번&lt;/strong&gt; 수행한 뒤의 θ₂ 를 구하라.&lt;br&gt;
  ② 이 학습률로 계속 반복하면 &lt;strong&gt;수렴&lt;/strong&gt;하는가, &lt;strong&gt;발산&lt;/strong&gt;하는가?
  &lt;div style="margin-top:0.4em;color:#666;font-size:0.92em;"&gt;
  힌트: 한 스텝의 갱신은 θ ← θ − η·2(θ − ${rH.a}) 이므로,
  최솟값 ${rH.a} 로부터의 거리는 매 스텝 &lt;strong&gt;|1 − 2η|&lt;/strong&gt; 배가 된다.
  &lt;/div&gt;`)







viewof rH_ans_t2 = Inputs.number({ label: "θ₂ =", step: 0.0001 })
viewof rH_ans_v = Inputs.radio(["수렴", "발산", "진동(제자리)"], { label: "판정" })
viewof rH_grade = Inputs.toggle({ label: "채점", value: false })
viewof rH_show = Inputs.toggle({ label: "풀이 보기", value: false })






























rH_grade ? dojoResult(
  [dojoMark("θ₂", dojoOk(rH_ans_t2, rH.t2, 0.0015)),
   dojoMark("수렴/발산 판정", rH_ans_v === rH.verdict)],
  dojoOk(rH_ans_t2, rH.t2, 0.0015) && rH_ans_v === rH.verdict
) : html``







rH_show ? dojoSolution(`
  &lt;strong&gt;스텝 1&lt;/strong&gt;: 기울기 = 2(${rH.th0} − ${rH.a}) = ${2 * (rH.th0 - rH.a)}&lt;br&gt;
  &nbsp;&nbsp;θ₁ = ${rH.th0} − ${rH.eta} × ${2 * (rH.th0 - rH.a)} = &lt;strong&gt;${rH.t1}&lt;/strong&gt;&lt;br&gt;
  &lt;strong&gt;스텝 2&lt;/strong&gt;: 기울기 = 2(${rH.t1} − ${rH.a}) = ${Math.round(2 * (rH.t1 - rH.a) * 100000) / 100000}&lt;br&gt;
  &nbsp;&nbsp;θ₂ = ${rH.t1} − ${rH.eta} × ${Math.round(2 * (rH.t1 - rH.a) * 100000) / 100000}
  = &lt;strong&gt;${rH.t2}&lt;/strong&gt;&lt;br&gt;&lt;br&gt;
  &lt;strong&gt;판정&lt;/strong&gt;: |1 − 2η| = |1 − ${2 * rH.eta}| = &lt;strong&gt;${rH.factor.toFixed(2)}&lt;/strong&gt;
  ${rH.factor &lt; 1 ? "&lt; 1 이므로 거리가 매 스텝 줄어든다 → &lt;strong&gt;수렴&lt;/strong&gt;"
    : rH.factor &gt; 1 ? "&gt; 1 이므로 거리가 매 스텝 커진다 → &lt;strong&gt;발산&lt;/strong&gt;"
    : "= 1 이므로 거리가 그대로다 → &lt;strong&gt;진동(제자리)&lt;/strong&gt;"}&lt;br&gt;
  &nbsp;&nbsp;최솟값까지의 거리: 처음 ${rH.d0} → 2스텝 후 ${rH.d2}&lt;br&gt;
  &lt;span style="color:#555;"&gt;학습률이 너무 크면 최솟값을 &lt;strong&gt;뛰어넘어&lt;/strong&gt; 반대편으로 더 멀리 간다.
  Ch03의 경사하강 인터랙티브에서 η를 0.9 이상으로 올렸을 때 본 현상이다.&lt;/span&gt;`) : html``

도장 사용법




대응 이론: Ch02 퍼셉트론과 다층 퍼셉트론
학번을 입력하면 나만의 문제가 나옵니다. 옆 사람과 다른 문제가 생성됩니다.
새 문제 버튼을 누르면 같은 유형의 다음 문제가 나옵니다. 무한히 연습할 수 있습니다.
답을 입력하고 채점을 켜면 즉시 확인됩니다. 막히면 풀이 보기 — 단, 먼저 손으로 계산해 보고 나서.
유형은 8개, 난이도는 [기본] → [응용] → [도전] 순입니다. 기본 3유형부터 시작하세요.
훈련 기준: 각 유형에서 연속 3문제 무실수가 되면 그 유형은 완성입니다.
// mulberry32 — 문제 번호(시드)가 같으면 항상 같은 문제가 생성된다
dojoRng = function (seed) {
  let a = (seed * 7919 + 104729) &gt;&gt;&gt; 0;
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a &gt;&gt;&gt; 15), 1 | a);
    t = (t + Math.imul(t ^ (t &gt;&gt;&gt; 7), 61 | t)) ^ t;
    return ((t ^ (t &gt;&gt;&gt; 14)) &gt;&gt;&gt; 0) / 4294967296;
  };
}
dojoInt = (rng, lo, hi) =&gt; lo + Math.floor(rng() * (hi - lo + 1))
dojoPick = (rng, arr) =&gt; arr[Math.floor(rng() * arr.length)]
// 정답 비교 — tol 이내면 정답 처리 (학생의 반올림 오차 허용)
dojoOk = (user, answer, tol = 0.005) =&gt;
  user !== null && user !== undefined && Number.isFinite(user) && Math.abs(user - answer) &lt;= tol
dojoMark = (label, ok, answerShown) =&gt; `
  &lt;div style="display:flex;align-items:center;gap:0.5em;padding:0.25em 0;"&gt;
    &lt;span style="font-size:1.1em;"&gt;${ok ? "✅" : "❌"}&lt;/span&gt;
    &lt;span style="font-weight:600;"&gt;${label}&lt;/span&gt;
    &lt;span style="color:${ok ? "#2E7D32" : "#8C1515"};"&gt;
      ${ok ? "정답" : (answerShown != null ? "오답 — 다시 계산해 보세요" : "오답")}
    &lt;/span&gt;
  &lt;/div&gt;`
// 문제 카드
dojoProblem = (title, bodyHtml) =&gt; html`
  &lt;div style="font-family:'Pretendard',sans-serif;border:1.5px solid #8C1515;border-radius:8px;
    overflow:hidden;margin:0.6em 0;max-width:720px;"&gt;
    &lt;div style="background:#8C1515;color:white;padding:0.4em 0.9em;font-weight:700;font-size:0.95em;"&gt;
      ${title}
    &lt;/div&gt;
    &lt;div style="padding:0.7em 0.9em;line-height:1.9;font-size:0.95em;"&gt;${bodyHtml}&lt;/div&gt;
  &lt;/div&gt;`
// 채점 결과 카드
dojoResult = (marks, allOk) =&gt; html`
  &lt;div style="font-family:'Pretendard',sans-serif;border-radius:8px;max-width:720px;margin:0.4em 0;
    padding:0.6em 0.9em;font-size:0.92em;
    background:${allOk ? "#E8F5E9" : "#FFF8E1"};
    border:1.5px solid ${allOk ? "#2E7D32" : "#D4A017"};"&gt;
    ${marks.join("")}
    &lt;div style="margin-top:0.35em;font-weight:700;color:${allOk ? "#2E7D32" : "#B8860B"};"&gt;
      ${allOk ? "🎉 전부 정답! 문제 번호를 바꿔 한 번 더 연습해 보세요." : "빨간 항목을 다시 풀어 보세요. 막히면 풀이 보기를 켜세요."}
    &lt;/div&gt;
  &lt;/div&gt;`
// 풀이 카드
dojoSolution = (stepsHtml) =&gt; html`
  &lt;div style="font-family:'Pretendard',sans-serif;border-radius:8px;max-width:720px;margin:0.4em 0;
    padding:0.7em 0.9em;background:#E3F2FD;border:1.5px solid #1565C0;
    line-height:2.0;font-size:0.92em;"&gt;
    &lt;div style="font-weight:700;color:#1565C0;margin-bottom:0.2em;"&gt;풀이&lt;/div&gt;
    ${stepsHtml}
  &lt;/div&gt;`
// FNV-1a — 학번 문자열을 정수로. 사람마다 다른 문제가 나오게 하는 출발점.
dojoHash = function (str) {
  let h = 2166136261 &gt;&gt;&gt; 0;
  const s = String(str);
  for (let i = 0; i &lt; s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 16777619) &gt;&gt;&gt; 0;
  }
  return h &gt;&gt;&gt; 0;
}
// (학번, 주차, 유형, 라운드) → 문제 번호.
// 학번이 다르면 다른 문제, 같은 학번·같은 라운드면 항상 같은 문제(재현 가능).
dojoSeed = function (sid, week, type, round) {
  const key = (sid && String(sid).trim()) ? String(sid).trim() : "guest";
  return (dojoHash(key + "|" + week + "|" + type + "|" + round) % 99999) + 1;
}
// 학번 입력 — 브라우저에 저장되어 모든 도장 페이지에서 유지된다.
viewof dojoSid = Inputs.text({
  label: "학번",
  placeholder: "예: 202312345",
  value: (() =&gt; { try { return localStorage.getItem("dojoSid") || ""; } catch (e) { return ""; } })(),
  width: 260
})
{
  try { localStorage.setItem("dojoSid", dojoSid || ""); } catch (e) {}
  const named = dojoSid && dojoSid.trim();
  return html`&lt;div style="font-family:'Pretendard',sans-serif;font-size:0.85em;
    padding:0.45em 0.8em;border-radius:6px;max-width:720px;margin:0.1em 0 0.9em;
    background:${named ? "#E8F5E9" : "#FFF8E1"};
    border:1px solid ${named ? "#A5D6A7" : "#E8D9A0"};color:${named ? "#2E7D32" : "#8A6D1B"};"&gt;
    ${named
      ? `학번 &lt;strong&gt;${dojoSid.trim()}&lt;/strong&gt; 기준으로 문제가 생성됩니다 — 옆 사람과 다른 문제가 나옵니다.`
      : `학번을 입력하면 &lt;strong&gt;나만의 문제 세트&lt;/strong&gt;가 만들어집니다. (비워 두면 공용 연습 문제)`}
  &lt;/div&gt;`;
}
// "새 문제" 버튼 + 문제 코드 표시를 한 줄로 묶는 헤더
dojoBar = (code) =&gt; html`
  &lt;div style="font-family:'Pretendard',sans-serif;font-size:0.82em;color:#666;
    margin:-0.3em 0 0.5em;"&gt;
    문제 코드 &lt;code style="background:#F1F3F5;padding:0.1em 0.4em;border-radius:4px;
