유형 A — 퍼셉트론 순전파 [기본]

viewof pA_round = Inputs.button("새 문제", { value: 0, reduce: (v) =&gt; v + 1 })







pA_seed = dojoSeed(dojoSid, 2, "A", pA_round)







pA = {
  const rng = dojoRng(pA_seed);
  const w0 = dojoInt(rng, -10, 10) / 10;
  let w1 = dojoInt(rng, -10, 10) / 10; if (w1 === 0) w1 = 0.5;
  let w2 = dojoInt(rng, -10, 10) / 10; if (w2 === 0) w2 = -0.5;
  const x1 = dojoInt(rng, 0, 3);
  const x2 = dojoInt(rng, 0, 3);
  const z = Math.round((w0 + w1 * x1 + w2 * x2) * 100) / 100;
  const yhat = z &gt;= 0 ? 1 : 0;
  return { w0, w1, w2, x1, x2, z, yhat };
}







dojoProblem(`문제 A-${pA_seed}`, `
  퍼셉트론의 가중치가 &lt;strong&gt;w₀ = ${pA.w0}&lt;/strong&gt; (편향),
  &lt;strong&gt;w₁ = ${pA.w1}&lt;/strong&gt;, &lt;strong&gt;w₂ = ${pA.w2}&lt;/strong&gt; 이고,
  활성화 함수는 &lt;strong&gt;계단 함수&lt;/strong&gt;(z ≥ 0이면 1, 아니면 0)이다.&lt;br&gt;
  입력이 &lt;strong&gt;(x₁, x₂) = (${pA.x1}, ${pA.x2})&lt;/strong&gt;일 때
  가중합 &lt;strong&gt;z&lt;/strong&gt;와 출력 &lt;strong&gt;ŷ&lt;/strong&gt;를 구하라.`)







viewof pA_ans_z = Inputs.number({ label: "z =", step: 0.01 })
viewof pA_ans_y = Inputs.number({ label: "ŷ =", step: 1 })
viewof pA_grade = Inputs.toggle({ label: "채점", value: false })
viewof pA_show = Inputs.toggle({ label: "풀이 보기", value: false })






























pA_grade ? dojoResult(
  [dojoMark("가중합 z", dojoOk(pA_ans_z, pA.z)),
   dojoMark("출력 ŷ", dojoOk(pA_ans_y, pA.yhat, 0.001))],
  dojoOk(pA_ans_z, pA.z) && dojoOk(pA_ans_y, pA.yhat, 0.001)
) : html``







pA_show ? dojoSolution(`
  ① 가중합: z = w₀ + w₁x₁ + w₂x₂ = ${pA.w0} + ${pA.w1}×${pA.x1} + ${pA.w2}×${pA.x2}
     = &lt;strong&gt;${pA.z}&lt;/strong&gt;&lt;br&gt;
  ② 계단 함수: z = ${pA.z} ${pA.z &gt;= 0 ? "≥ 0 이므로" : "&lt; 0 이므로"}
     ŷ = &lt;strong&gt;${pA.yhat}&lt;/strong&gt;`) : html``

유형 B — 활성화 함수 값 [기본]

viewof pB_round = Inputs.button("새 문제", { value: 0, reduce: (v) =&gt; v + 1 })







pB_seed = dojoSeed(dojoSid, 2, "B", pB_round)







pB = {
  const rng = dojoRng(pB_seed + 50000);
  let z = dojoInt(rng, -30, 30) / 10; if (z === 0) z = 1.0;
  const sig = Math.round(1 / (1 + Math.exp(-z)) * 100) / 100;
  const relu = Math.max(0, z);
  return { z, sig, relu };
}







dojoProblem(`문제 B-${pB_seed}`, `
  가중합이 &lt;strong&gt;z = ${pB.z}&lt;/strong&gt;로 계산되었다. (계산기 사용 가능)&lt;br&gt;
  ① Sigmoid: σ(z) = 1/(1+e&lt;sup&gt;−z&lt;/sup&gt;) 의 값을 &lt;strong&gt;소수 둘째 자리까지&lt;/strong&gt; 구하라.&lt;br&gt;
  ② ReLU: max(0, z) 의 값을 구하라.`)







viewof pB_ans_sig = Inputs.number({ label: "σ(z) =", step: 0.01 })
