viewof pB_grade = Inputs.toggle({ label: "채점", value: false })
viewof pB_show = Inputs.toggle({ label: "풀이 보기", value: false })






























pB_grade ? dojoResult(
  [dojoMark("Sigmoid σ(z)", dojoOk(pB_ans_sig, pB.sig, 0.006)),
   dojoMark("ReLU(z)", dojoOk(pB_ans_relu, pB.relu, 0.001))],
  dojoOk(pB_ans_sig, pB.sig, 0.006) && dojoOk(pB_ans_relu, pB.relu, 0.001)
) : html``







pB_show ? dojoSolution(`
  ① σ(${pB.z}) = 1 / (1 + e&lt;sup&gt;${-pB.z &gt; 0 ? "" : "−"}${Math.abs(pB.z)}&lt;/sup&gt;)
     = 1 / (1 + ${(Math.exp(-pB.z)).toFixed(4)}) ≈ &lt;strong&gt;${pB.sig.toFixed(2)}&lt;/strong&gt;&lt;br&gt;
  ② z = ${pB.z} ${pB.z &gt; 0 ? "&gt; 0 이므로 그대로" : "≤ 0 이므로 0"}:
     ReLU(${pB.z}) = &lt;strong&gt;${pB.relu}&lt;/strong&gt;&lt;br&gt;
  &lt;span style="color:#555;"&gt;σ(z)는 z가 클수록 1에, 작을수록 0에 가까워진다 — 그래프로 확인: Ch02 활성화 함수 절.&lt;/span&gt;`) : html``

