viewof pD_grade = Inputs.toggle({ label: "채점", value: false })
viewof pD_show = Inputs.toggle({ label: "풀이 보기", value: false })























pD_grade ? dojoResult(
  [dojoMark("게이트 판정", pD_ans === pD.name)],
  pD_ans === pD.name
) : html``







