pE_seed = dojoSeed(dojoSid, 2, "E", pE_round)







pE = {
  const rng = dojoRng(pE_seed + 300000);
  const w0 = dojoInt(rng, -10, 10) / 10;
  let w1 = dojoInt(rng, -8, 8) / 10; if (w1 === 0) w1 = 0.3;
