인터랙티브 — 박스를 움직여 IoU의 감각을 익히세요



박스 B의 위치와 크기를 조절하면서 IoU가 어떻게 변하는지 확인하세요. “IoU 0.5”가 시각적으로 얼마나 빡빡한 기준인지 감각을 잡는 것이 목표입니다.








viewof iouBx = Inputs.range([0, 8], { step: 0.5, label: "B의 x₁", value: 4 })
viewof iouBy = Inputs.range([0, 6], { step: 0.5, label: "B의 y₁", value: 3 })
viewof iouBw = Inputs.range([1, 8], { step: 0.5, label: "B의 너비", value: 4 })
viewof iouBh = Inputs.range([1, 6], { step: 0.5, label: "B의 높이", value: 3 })






























iouCalc = {
  const a = { x1: 2, y1: 2, x2: 6, y2: 5 };
  const b = { x1: iouBx, y1: iouBy, x2: iouBx + iouBw, y2: iouBy + iouBh };
  const ix1 = Math.max(a.x1, b.x1), iy1 = Math.max(a.y1, b.y1);
  const ix2 = Math.min(a.x2, b.x2), iy2 = Math.min(a.y2, b.y2);
  const iw = Math.max(0, ix2 - ix1), ih = Math.max(0, iy2 - iy1);
  const inter = iw * ih;
  const areaA = (a.x2 - a.x1) * (a.y2 - a.y1);
  const areaB = (b.x2 - b.x1) * (b.y2 - b.y1);
  const union = areaA + areaB - inter;
  return { a, b, ix1, iy1, iw, ih, inter, areaA, areaB, union, iou: inter / union };
}









{
  const s = 42, pad = 30;
  const W = 12 * s + pad * 2, H = 9 * s + pad * 2;
  const c = iouCalc;

  const svg = d3.create("svg")
    .attr("viewBox", `0 0 ${W} ${H}`)
    .attr("width", "100%")
    .style("max-width", "560px")
    .style("font-family", "Pretendard, sans-serif");

  // grid
  for (let i = 0; i &lt;= 12; i++)
    svg.append("line").attr("x1", pad + i * s).attr("y1", pad).attr("x2", pad + i * s).attr("y2", pad + 9 * s)
      .attr("stroke", "#eee");
  for (let j = 0; j &lt;= 9; j++)
    svg.append("line").attr("x1", pad).attr("y1", pad + j * s).attr("x2", pad + 12 * s).attr("y2", pad + j * s)
      .attr("stroke", "#eee");

  const rect = (b, fill, stroke, label) =&gt; {
    svg.append("rect")
      .attr("x", pad + b.x1 * s).attr("y", pad + b.y1 * s)
      .attr("width", (b.x2 - b.x1) * s).attr("height", (b.y2 - b.y1) * s)
      .attr("fill", fill).attr("fill-opacity", 0.25)
      .attr("stroke", stroke).attr("stroke-width", 2.5).attr("rx", 3);
    svg.append("text")
      .attr("x", pad + b.x1 * s + 8).attr("y", pad + b.y1 * s + 18)
      .attr("font-size", "13").attr("font-weight", "700").attr("fill", stroke).text(label);
  };

  rect(c.a, "#1F3F7A", "#1F3F7A", "A");
  rect(c.b, "#E65100", "#E65100", "B");

  // intersection
  if (c.inter &gt; 0) {
    svg.append("rect")
      .attr("x", pad + c.ix1 * s).attr("y", pad + c.iy1 * s)
      .attr("width", c.iw * s).attr("height", c.ih * s)
      .attr("fill", "#2E7D32").attr("fill-opacity", 0.45)
      .attr("stroke", "#2E7D32").attr("stroke-width", 1.5);
  }

  return svg.node();
}








html`&lt;div style="font-family:'Pretendard',sans-serif;font-size:0.85em;"&gt;

