biasY = [90, 20, 95]
biasRows = biasBase.map((b, i) =&gt; {
  const yhat = b + (biasW0 + 10)
  return { student: i + 1, yhat, y: biasY[i], loss: (biasY[i] - yhat) ** 2 }
