  format: k =&gt; k === "step" ? "계단 함수" : k === "identity" ? "항등 함수" : "시그모이드"
})






























pInputs = [[0,0],[1,0],[0,1],[1,1]]
pRows = pInputs.map(([x1,x2]) =&gt; {
  const z = pw0 + pw1*x1 + pw2*x2
  let y
  if (pActFn === "step") y = z &gt;= 0 ? 1 : 0
  else if (pActFn === "identity") y = z
  else y = 1 / (1 + Math.exp(-z))
  return { x1, x2, z, y }
})
pPattern = pRows.map(r =&gt; pActFn === "step" ? r.y : r.y.toFixed(2)).join(", ")

























