코드
import pandas as pd

rows = []
for x1, x2 in [(0, 0), (1, 0), (0, 1), (1, 1)]:
    z1 = -0.3 + 0.5*x1 + 0.5*x2
    s1 = 1 if z1 &gt;= 0 else 0
    z2 = 0.7 - 0.5*x1 - 0.5*x2
    s2 = 1 if z2 &gt;= 0 else 0
    z3 = -0.7 + 0.5*s1 + 0.5*s2
    y_hat = 1 if z3 &gt;= 0 else 0
    xor_target = x1 ^ x2
    rows.append({
        '$x_1$': x1, '$x_2$': x2,
        '$s_1$': s1, '$s_2$': s2,
        '$z_3 = -0.7 + 0.5 s_1 + 0.5 s_2$': f'{z3:+.1f}',
        'ŷ': y_hat,
        'XOR 정답': xor_target,
        '일치': '✓' if y_hat == xor_target else '✗',
    })

pd.DataFrame(rows).to_html(index=False, border=0, escape=False)




