  const kbox = d3.create("div").style("text-align", "center").style("font-family", "Pretendard, sans-serif").style("flex", "0 0 150px").style("align-self", "center");
  kbox.append("div").style("font-weight", "700").style("margin-bottom", "0.3em").text("커널 (3×3)");
  const tbl = kbox.append("table").style("margin", "0 auto").style("border-collapse", "collapse");
  for (const row of ker) { const tr = tbl.append("tr"); for (const v of row) tr.append("td").style("border", "1px solid #E65100").style("background", "#FFE0B2").style("width", "34px").style("height", "30px").style("text-align", "center").style("font-size", "0.9em").text(Number.isInteger(v) ? v : v.toFixed(2)); }
  kbox.append("div").style("font-size", "1.6em").style("margin-top", "0.4em").text("⊗  =");
  const wrap = d3.create("div").style("display", "flex").style("gap", "14px").style("align-items", "flex-start").style("justify-content", "center").style("flex-wrap", "wrap");
  wrap.append(() =&gt; draw(img, n, v =&gt; v, "이미지", `${n} × ${n}, 픽셀 값 0~255`));
  wrap.append(() =&gt; kbox.node());
  wrap.append(() =&gt; draw(fmap, m, v =&gt; 255 * v / mx, "특성 맵", `${m} × ${m}. 값이 클수록 밝게. 최댓값 ${Math.round(mx)}, 0 이하는 검정`));
  return wrap.node();
}






세로 에지 커널을 고르면 건물의 세로 기둥과 벽의 왼쪽 경계만 밝게 남고, 가로 에지 커널을 고르면 지붕선과 처마만 밝게 남는다. 방향을 반대로 뒤집은 커널은 반대쪽 경계를 잡아낸다. 같은 이미지인데 커널마다 하이라이팅되는 곳이 다르다. 커널 하나가 특성 하나를 골라내고, 특성 맵은 그 특성이 어디에 있는지를 밝기로 보여 준다. 평균 커널을 고르면 어디에도 특별히 반응하지 않고 이미지가 뭉개지기만 한다. 특성을 골라내는 커널이 아니기 때문이다.

옛 컴퓨터 비전에서는 이런 커널을 사람이 직접 설계했다. CNN에서는 커널의 값을 데이터로부터 학습한다. 어떤 패턴이 분류에 유용한지를 데이터가 정한다.



여러 개의 커널을 함께 쓴다
커널 하나는 특성 하나를 골라낸다. 앞 장에서 사람은 눈·코·입처럼 특성을 여러 개 본다고 했다. 이미지에서 서로 다른 특성을 여러 개 포착하려면 여러 개의 커널을 같은 이미지에 적용한다. 커널이 3개면 특성 맵도 3장이다.

{
  const img = fm_images["건물 사진 (64×64)"];
  const kers = [["세로 에지", [[1,0,-1],[1,0,-1],[1,0,-1]]], ["가로 에지", [[1,1,1],[0,0,0],[-1,-1,-1]]], ["대각선 에지", [[2,1,0],[1,0,-1],[0,-1,-2]]]];
  const n = img.length, m = n - 2, cell = 3;
  const pix = (mat, size, scale) =&gt; {
    const svg = d3.create("svg").attr("viewBox", `0 0 ${size*cell} ${size*cell}`).attr("width", size*cell).attr("height", size*cell).style("background", "#000").style("display", "block").style("margin", "0 auto");
    for (let r = 0; r &lt; size; r++) for (let c = 0; c &lt; size; c++) { const v = Math.max(0, Math.min(255, Math.round(scale(mat[r][c])))); svg.append("rect").attr("x", c*cell).attr("y", r*cell).attr("width", cell).attr("height", cell).attr("fill", `rgb(${v},${v},${v})`); }
    return svg.node();
  };
  const conv = ker =&gt; { const out = []; let mx = 1e-9; for (let r = 0; r &lt; m; r++) { const row = []; for (let c = 0; c &lt; m; c++) { let s = 0; for (let i = 0; i &lt; 3; i++) for (let j = 0; j &lt; 3; j++) s += img[r+i][c+j]*ker[i][j]; row.push(s); mx = Math.max(mx, s); } out.push(row); } return [out, mx]; };
  const wrap = d3.create("div").style("display", "flex").style("gap", "18px").style("align-items", "center").style("justify-content", "center").style("flex-wrap", "wrap").style("font-family", "Pretendard, sans-serif");
  const left = wrap.append("div").style("text-align", "center"); left.append("div").style("font-weight", "700").style("margin-bottom", "0.3em").text("이미지 (1장)"); left.append(() =&gt; pix(img, n, v =&gt; v));
  wrap.append("div").style("font-size", "1.8em").text("⊗");
  const kcol = wrap.append("div").style("display", "flex").style("flex-direction", "column").style("gap", "10px");
  const ocol = wrap.append("div").style("display", "flex").style("flex-direction", "column").style("gap", "10px");
  for (const [name, ker] of kers) {
    const kb = kcol.append("div").style("text-align", "center"); kb.append("div").style("font-size", "0.85em").style("font-weight", "600").text(`커널: ${name}`);
    const tbl = kb.append("table").style("margin", "0 auto").style("border-collapse", "collapse");
    for (const row of ker) { const tr = tbl.append("tr"); for (const v of row) tr.append("td").style("border", "1px solid #E65100").style("background", "#FFE0B2").style("width", "22px").style("height", "20px").style("text-align", "center").style("font-size", "0.75em").text(v); }
    const [fm, mx] = conv(ker);
    const ob = ocol.append("div").style("text-align", "center"); ob.append("div").style("font-size", "0.85em").style("font-weight", "600").text(`특성 맵: ${name}`); ob.append(() =&gt; pix(fm, m, v =&gt; 255*v/mx));
  }
  wrap.insert("div", () =&gt; ocol.node()).style("font-size", "1.8em").text("=");
  return wrap.node();
}






세 장의 특성 맵은 각각 세로 경계, 가로 경계, 대각선 경계가 어디에 있는지를 따로 기록한다. 커널이 \(K\)개면 특성 맵도 \(K\)장이고, 이 \(K\)장이 다음 단계의 재료가 된다.

콘볼루션 연산의 파라미터
지금까지는 \(5 \times 5\) 이미지에 \(3 \times 3\) 커널을 한 칸씩 옮겼다. 이 셋을 바꾸면 특성 맵의 크기가 달라진다. 세 가지를 차례로 정한다.

커널 크기 (Kernel Size)






커널 크기 (Kernel Size)



커널의 한 변의 픽셀 수. 패턴을 얼마나 크게 볼 것인가를 정한다. 이미지 처리에서는 가로·세로가 같은 정사각형을 쓴다.



convGeo = (N, K, S, P, title, cur = null) =&gt; {
  const cs = 22, gap = 2, T = N + 2 * P;
  const out = Math.floor((N - K + 2 * P) / S) + 1;
  const ci = cur === null ? 0 : Math.min(cur, out * out - 1), cr = Math.floor(ci / out), cc = ci % out;
  const W = T * (cs + gap) + gap + 40 + out * (cs + gap) + gap, H = Math.max(T, out) * (cs + gap) + gap + 44;
  const svg = d3.create("svg").attr("viewBox", `0 0 ${W} ${H}`).attr("width", W).attr("height", H).style("font-family", "Pretendard, sans-serif");
  svg.append("text").attr("x", (T * (cs + gap)) / 2).attr("y", 14).attr("text-anchor", "middle").attr("font-size", "11.5").attr("font-weight", "700").attr("fill", "#333").text(title);
  const y0 = 24;
  for (let r = 0; r &lt; T; r++) for (let c = 0; c &lt; T; c++) {
    const pad = r &lt; P || c &lt; P || r &gt;= T - P || c &gt;= T - P;
    svg.append("rect").attr("x", gap + c * (cs + gap)).attr("y", y0 + gap + r * (cs + gap)).attr("width", cs).attr("height", cs).attr("rx", 2)
      .attr("fill", pad ? "#ECEFF1" : "#C8E6C9").attr("stroke", pad ? "#B0BEC5" : "#4CAF50").attr("stroke-dasharray", pad ? "3,2" : null);
    if (pad) svg.append("text").attr("x", gap + c * (cs + gap) + cs / 2).attr("y", y0 + gap + r * (cs + gap) + cs / 2 + 4).attr("text-anchor", "middle").attr("font-size", "10").attr("fill", "#90A4AE").text("0");
  }
  // 현재(또는 첫) 커널 자리
  svg.append("rect").attr("x", gap + cc * S * (cs + gap)).attr("y", y0 + gap + cr * S * (cs + gap)).attr("width", K * (cs + gap) - gap).attr("height", K * (cs + gap) - gap).attr("fill", "#FFF9C4").attr("fill-opacity", 0.55).attr("stroke", "#F57F17").attr("stroke-width", 2.5);
  // 모든 자리의 중심점
  for (let i = 0; i &lt; out; i++) for (let j = 0; j &lt; out; j++) {
    const cx = gap + (j * S) * (cs + gap) + (K * (cs + gap) - gap) / 2, cy = y0 + gap + (i * S) * (cs + gap) + (K * (cs + gap) - gap) / 2;
    svg.append("circle").attr("cx", cx).attr("cy", cy).attr("r", 3.5).attr("fill", "#C62828");
  }
  svg.append("text").attr("x", (T * (cs + gap)) / 2).attr("y", H - 6).attr("text-anchor", "middle").attr("font-size", "10.5").attr("fill", "#555")
    .text(`입력 ${N}×${N}${P ? ` + 패딩 ${P}` : ""}, 커널 ${K}×${K}, 스트라이드 ${S}. 빨간 점 = 커널이 놓이는 자리 ${out}×${out}`);
  const ox = T * (cs + gap) + gap + 40;
  svg.append("text").attr("x", ox - 20).attr("y", y0 + (T * (cs + gap)) / 2 + 6).attr("text-anchor", "middle").attr("font-size", "18").attr("fill", "#555").text("→");
  const oy = y0 + gap + ((T - out) * (cs + gap)) / 2;
  for (let r = 0; r &lt; out; r++) for (let c = 0; c &lt; out; c++) {
    const done = cur !== null && r * out + c &lt;= ci, isCur = cur !== null && r * out + c === ci;
    svg.append("rect").attr("x", ox + c * (cs + gap)).attr("y", oy + r * (cs + gap)).attr("width", cs).attr("height", cs).attr("rx", 2)
      .attr("fill", isCur ? "#FFCDD2" : done ? "#F8BBD0" : "#FFEBEE").attr("stroke", isCur ? "#C62828" : "#E57373").attr("stroke-width", isCur ? 2.5 : 1);
  }
  if (cur !== null) svg.append("text").attr("x", ox + (out * (cs + gap)) / 2).attr("y", H - 6).attr("text-anchor", "middle").attr("font-size", "10.5").attr("fill", "#C62828").text(`스텝 ${ci + 1} / ${out * out}`);
  svg.append("text").attr("x", ox + (out * (cs + gap)) / 2).attr("y", 14).attr("text-anchor", "middle").attr("font-size", "11.5").attr("font-weight", "700").attr("fill", "#C62828").text(`특성 맵 ${out}×${out}`);
  return svg.node();
}






같은 이미지에 커널 크기만 바꿔 보자. 노란 칸이 커널이 처음 놓이는 자리, 빨간 점이 커널이 놓일 수 있는 모든 자리의 중심이다. 슬라이더로 커널을 키우면 놓일 자리가 줄어 특성 맵이 작아진다.

viewof geoK = Inputs.range([1, 5], { step: 1, label: "커널 크기 K", value: 3 })







mutable kszStep = 0
mutable kszPlaying = false
kszOut = Math.floor((7 - geoK) / 1) + 1
viewof kszCtl = Inputs.button([
  ["▸ 다음 스텝", () =&gt; { mutable kszPlaying = false; if (kszStep &lt; kszOut * kszOut - 1) mutable kszStep = kszStep + 1; return kszStep }],
  ["▶ 재생", () =&gt; { mutable kszPlaying = true; return kszStep }],
  ["↺ 처음으로", () =&gt; { mutable kszPlaying = false; mutable kszStep = 0; return 0 }]
])
kszReset = { geoK; mutable kszPlaying = false; mutable kszStep = 0; return true }
kszPlayer = {
  if (!kszPlaying) return false
  while (kszPlaying && kszStep &lt; kszOut * kszOut - 1) { await Promises.delay(350); mutable kszStep = kszStep + 1; yield true }
  mutable kszPlaying = false; return false
}












































html`&lt;div style="display:flex;justify-content:center;"&gt;${convGeo(7, geoK, 1, 0, `7×7 이미지, 커널 크기 ${geoK}`, kszStep)}&lt;/div&gt;`






\(7 \times 7\) 이미지에서 커널 크기 2, 3, 4, 5이면 특성 맵은 각각 \(6 \times 6\), \(5 \times 5\), \(4 \times 4\), \(3 \times 3\)이다. 커널이 한 칸 커질 때마다 특성 맵이 한 칸 줄어든다.


스트라이드 (Stride)






스트라이드 (Stride, 보폭)



커널이 한 번에 몇 픽셀씩 이동하는가. 이미지를 얼마나 자세히 훑을지를 정한다.

스트라이드 1: 가로·세로로 한 픽셀씩 이동. 지금까지 한 것
스트라이드 2: 두 픽셀씩 이동. 놓이는 자리가 절반으로 줄어 특성 맵도 대략 절반 크기가 된다




viewof geoS = Inputs.range([1, 3], { step: 1, label: "스트라이드 S", value: 1 })







mutable geoStep = 0
mutable geoPlaying = false
geoOut = Math.floor((7 - 3) / geoS) + 1
viewof geoCtl = Inputs.button([
  ["▸ 다음 스텝", () =&gt; { mutable geoPlaying = false; if (geoStep &lt; geoOut * geoOut - 1) mutable geoStep = geoStep + 1; return geoStep }],
  ["▶ 재생", () =&gt; { mutable geoPlaying = true; return geoStep }],
  ["↺ 처음으로", () =&gt; { mutable geoPlaying = false; mutable geoStep = 0; return 0 }]
])
geoReset = { geoS; mutable geoPlaying = false; mutable geoStep = 0; return true }
geoPlayer = {
  if (!geoPlaying) return false
  while (geoPlaying && geoStep &lt; geoOut * geoOut - 1) { await Promises.delay(450); mutable geoStep = geoStep + 1; yield true }
  mutable geoPlaying = false; return false
}












































html`&lt;div style="display:flex;justify-content:center;"&gt;${convGeo(7, 3, geoS, 0, `7×7 이미지, 3×3 커널, 스트라이드 ${geoS}`, geoStep)}&lt;/div&gt;`






재생을 누르면 커널(노랑)이 스트라이드만큼 건너뛰며 이동하고, 특성 맵의 칸이 하나씩 채워진다. 스트라이드 1이면 자리가 \(5 \times 5\), 2면 \(3 \times 3\), 3이면 \(2 \times 2\)다.


패딩 (Padding)






패딩 (Padding)



이미지의 테두리에 의미 없는 값(0)을 두께 \(P\)만큼 둘러 이미지를 키우는 것.
패딩을 하지 않으면 콘볼루션마다 특성 맵이 줄어든다. 테두리에 0을 한 겹(\(P = 1\)) 두르고 \(3 \times 3\) 커널을 스트라이드 1로 훑으면 원본과 같은 크기의 특성 맵을 얻는다.



viewof geoP = Inputs.range([0, 2], { step: 1, label: "패딩 P", value: 0 })







mutable padStep = 0
mutable padPlaying = false
padOut = 5 - 3 + 2 * geoP + 1
viewof padCtl = Inputs.button([
  ["▸ 다음 스텝", () =&gt; { mutable padPlaying = false; if (padStep &lt; padOut * padOut - 1) mutable padStep = padStep + 1; return padStep }],
  ["▶ 재생", () =&gt; { mutable padPlaying = true; return padStep }],
  ["↺ 처음으로", () =&gt; { mutable padPlaying = false; mutable padStep = 0; return 0 }]
])
padReset = { geoP; mutable padPlaying = false; mutable padStep = 0; return true }
padPlayer = {
  if (!padPlaying) return false
  while (padPlaying && padStep &lt; padOut * padOut - 1) { await Promises.delay(350); mutable padStep = padStep + 1; yield true }
  mutable padPlaying = false; return false
}












































html`&lt;div style="display:flex;justify-content:center;"&gt;${convGeo(5, 3, 1, geoP, geoP ? `5×5 이미지 + 패딩 ${geoP}, 3×3 커널` : "5×5 이미지, 패딩 없음, 3×3 커널", padStep)}&lt;/div&gt;`






회색 점선 칸이 둘러 준 0이다. 재생을 누르면 커널이 0으로 채운 테두리까지 밟고 지나가는 것이 보인다. 패딩 없이 \(5 \times 5\)에 \(3 \times 3\) 커널이면 \(3 \times 3\)으로 줄지만, 0을 한 겹 두르면(\(P=1\)) 커널이 놓일 자리가 \(5 \times 5\)로 늘어 원본 크기가 유지된다. 두 겹이면 원본보다 커진다.

특성 맵의 크기 공식
세 파라미터를 하나씩 바꿔 보았다. 셋을 한 식으로 묶으면 특성 맵의 크기를 바로 계산할 수 있다. 입력 크기 \(N\), 커널 크기 \(K\), 패딩 \(P\), 스트라이드 \(S\)일 때
\[\text{출력 크기} = \left\lfloor \frac{N - K + 2P}{S} \right\rfloor + 1\]
읽는 법: 패딩까지 포함한 이미지 폭 \(N + 2P\)에서 커널 폭 \(K\)를 빼면 커널이 더 움직일 수 있는 거리다. 그것을 보폭 \(S\)로 나누면 더 움직일 수 있는 횟수고, 처음 놓인 자리 1을 더한다.






\(\lfloor\ \rfloor\)는 버림이다



\(\lfloor 15.5 \rfloor = 15\). 반올림이 아니라 소수점 이하를 무조건 버린다. 커널이 이동하다 이미지 밖으로 나가는 자리는 계산할 수 없어 그 자리를 버리기 때문이다. 가장 흔한 실수 두 가지는 마지막 \(+1\)을 빼먹는 것과 버림을 반올림으로 하는 것이다.


앞의 세 그림을 공식으로 확인하면 커널 크기 3에서 \(\lfloor (7-3)/1 \rfloor + 1 = 5\), 스트라이드 2에서 \(\lfloor (7-3)/2 \rfloor + 1 = 3\), 패딩 1에서 \(\lfloor (5-3+2)/1 \rfloor + 1 = 5\)다. 그림의 빨간 점 개수와 같다.

크기를 유지하는 패딩
공식에서 스트라이드 1일 때 출력이 입력과 같아지려면 \(N - K + 2P + 1 = N\), 즉
\[P = \frac{K - 1}{2}\]
이다. 이렇게 크기를 유지하는 패딩을 코드에서는 same, 패딩 없음을 valid라 부른다. \(P\)가 정수가 되려면 \(K\)가 홀수여야 한다. 커널 크기로 3, 5, 7을 쓰는 이유가 이것이다. 홀수면 커널의 중심 픽셀도 하나로 정해진다.


✍️ 손으로 따라 계산하기 — 출력 크기
연습 1 — 기본. \(N=7,\ K=3,\ P=0,\ S=1\)
\[\left\lfloor \frac{7 - 3 + 0}{1} \right\rfloor + 1 = 4 + 1 = \mathbf{5}\]
연습 2 — 나누어떨어지지 않는 경우. \(N=32,\ K=5,\ P=2,\ S=2\)
\[\left\lfloor \frac{32 - 5 + 4}{2} \right\rfloor + 1 = \lfloor 15.5 \rfloor + 1 = 15 + 1 = \mathbf{16}\]
\(15.5\)를 16으로 반올림하면 오답이다. 버려서 15, 거기에 1을 더해 16이다.
연습 3 — 크기 유지 (same). \(N=28,\ K=3,\ P=1,\ S=1\)
\[\left\lfloor \frac{28 - 3 + 2}{1} \right\rfloor + 1 = 27 + 1 = \mathbf{28}\]






✍️ 직접 해보기





\(N=64,\ K=7,\ P=3,\ S=2\)일 때 출력 크기는? 정답을 보기 전에 손으로 먼저 계산하라.
\(\left\lfloor \dfrac{64 - 7 + 6}{2} \right\rfloor + 1 = \lfloor 31.5 \rfloor + 1 = 31 + 1 = \mathbf{32}\). 스트라이드 2가 크기를 대략 절반으로 줄인다.









인터랙티브 — 종합 연습: 네 값을 함께 바꾸기



