  const W = (xmax - xmin) * s + pad * 2, H = (ymax - ymin) * s + pad * 2;
  const px = x =&gt; pad + (x - xmin) * s;
  const py = y =&gt; pad + (ymax - y) * s;
  const cA = "#1F3F7A", cB = "#E65100";

  const svg = d3.create("svg")
    .attr("viewBox", `0 0 ${W} ${H}`)
    .attr("width", "100%")
    .style("max-width", "540px")
    .style("font-family", "Pretendard, sans-serif");

  // grid
  for (let i = xmin; i &lt;= xmax; i++)
    svg.append("line").attr("x1", px(i)).attr("y1", py(ymin)).attr("x2", px(i)).attr("y2", py(ymax))
      .attr("stroke", i === 0 ? "#bbb" : "#f0f0f0").attr("stroke-width", i === 0 ? 1.5 : 1);
  for (let j = ymin; j &lt;= ymax; j++)
    svg.append("line").attr("x1", px(xmin)).attr("y1", py(j)).attr("x2", px(xmax)).attr("y2", py(j))
      .attr("stroke", j === 0 ? "#bbb" : "#f0f0f0").attr("stroke-width", j === 0 ? 1.5 : 1);

  // arrow markers
  const defs = svg.append("defs");
  for (const [id, color] of [["arrA", cA], ["arrB", cB]]) {
    defs.append("marker").attr("id", id)
      .attr("viewBox", "0 0 10 10").attr("refX", 8).attr("refY", 5)
      .attr("markerWidth", 6).attr("markerHeight", 6).attr("orient", "auto-start-reverse")
      .append("path").attr("d", "M 0 0 L 10 5 L 0 10 z").attr("fill", color);
  }

  // all word points
  for (const d of embWords) {
    const sel = d.word === wordA || d.word === wordB;
    svg.append("circle").attr("cx", px(d.x)).attr("cy", py(d.y)).attr("r", sel ? 6 : 4)
      .attr("fill", d.word === wordA ? cA : d.word === wordB ? cB : "#999");
    svg.append("text").attr("x", px(d.x) + 8).attr("y", py(d.y) - 7)
      .attr("font-size", sel ? "13" : "11.5").attr("font-weight", sel ? "700" : "400")
      .attr("fill", d.word === wordA ? cA : d.word === wordB ? cB : "#666").text(d.word);
  }

  // vectors from origin
  const c = simCalc;
  svg.append("line").attr("x1", px(0)).attr("y1", py(0)).attr("x2", px(c.a.x)).attr("y2", py(c.a.y))
    .attr("stroke", cA).attr("stroke-width", 3).attr("marker-end", "url(#arrA)");
  svg.append("line").attr("x1", px(0)).attr("y1", py(0)).attr("x2", px(c.b.x)).attr("y2", py(c.b.y))
    .attr("stroke", cB).attr("stroke-width", 3).attr("marker-end", "url(#arrB)");

  svg.append("circle").attr("cx", px(0)).attr("cy", py(0)).attr("r", 3).attr("fill", "#333");
  svg.append("text").attr("x", px(0) + 6).attr("y", py(0) + 15)
    .attr("font-size", "11").attr("fill", "#888").text("원점");

  return svg.node();
}








