유형 A — 변수의 종류 구분 [기본]

viewof qA_round = Inputs.button("새 문제", { value: 0, reduce: (v) =&gt; v + 1 })







qA_seed = dojoSeed(dojoSid, 1, "A", qA_round)







qA = {
  const rng = dojoRng(qA_seed);
  const pool = d1vars.slice();
  for (let i = pool.length - 1; i &gt; 0; i--) {
    const j = Math.floor(rng() * (i + 1));
    [pool[i], pool[j]] = [pool[j], pool[i]];
  }
  const picked = pool.slice(0, 6);
  const nNum = picked.filter(v =&gt; v.t === "숫자형").length;
  return { picked, nNum, nCat: 6 - nNum };
}







