유형 D — 모형과 파라미터 식별 [응용]

viewof qD_round = Inputs.button("새 문제", { value: 0, reduce: (v) =&gt; v + 1 })







qD_seed = dojoSeed(dojoSid, 1, "D", qD_round)







sub = (n) =&gt; String(n).split("").map(c =&gt; "₀₁₂₃₄₅₆₇₈₉"[+c]).join("")







sup = (n) =&gt; String(n).split("").map(c =&gt; "⁰¹²³⁴⁵⁶⁷⁸⁹"[+c]).join("")







qD = {
  const rng = dojoRng(qD_seed);
  const kind = dojoInt(rng, 0, 1);
  if (kind === 0) {
    const deg = dojoInt(rng, 2, 6);
    const terms = [];
    for (let k = 1; k &lt;= deg; k++) terms.push(`w${sub(k)}x${k &gt; 1 ? sup(k) : ""}`);
    return {
      expr: `y = w₀ + ${terms.join(" + ")}`,
      nParam: deg + 1,
      why: `${deg}차 다항식은 w₀부터 w${sub(deg)}까지 — &lt;strong&gt;차수 + 1 = ${deg + 1}&lt;/strong&gt;개`
    };
  } else {
    const m = dojoInt(rng, 3, 7);
    const terms = [];
    for (let k = 1; k &lt;= m; k++) terms.push(`w${sub(k)}x${sub(k)}`);
    return {
      expr: `y = w₀ + ${terms.join(" + ")}`,
      nParam: m + 1,
      why: `독립변수 ${m}개마다 가중치 1개, 그리고 편향 w₀ 1개 — &lt;strong&gt;${m} + 1 = ${m + 1}&lt;/strong&gt;개`
    };
  }
}







