qH = {
  const rng = dojoRng(qH_seed);
  const xs = [1, 2, 3, 4];
  const tw0 = dojoInt(rng, 1, 6);
  const tw1 = dojoInt(rng, 2, 5);
  const ys = xs.map(x =&gt; tw0 + tw1 * x + dojoInt(rng, -2, 2));
  const A = { w0: tw0 + dojoInt(rng, -1, 1), w1: tw1 };
