  const sse = (p) =&gt; xs.reduce((s, x, i) =&gt; s + Math.pow(ys[i] - (p.w0 + p.w1 * x), 2), 0);
  const sA = sse(A), sB = sse(B);
  return { xs, ys, A, B, sA, sB, best: sA &lt;= sB ? "A" : "B" };
}







