유형 A — MSE 계산 [기본]

viewof rA_round = Inputs.button("새 문제", { value: 0, reduce: (v) =&gt; v + 1 })







rA_seed = dojoSeed(dojoSid, 3, "A", rA_round)







rA = {
  const rng = dojoRng(rA_seed);
  const n = dojoInt(rng, 4, 5);
  const ys = [], hs = [];
  for (let i = 0; i &lt; n; i++) {
    const y = dojoInt(rng, 150, 190);
    const e = dojoInt(rng, -6, 6);
    ys.push(y); hs.push(y - e);
  }
  const errs = ys.map((y, i) =&gt; y - hs[i]);
  const sq = errs.map(e =&gt; e * e);
  const sum = sq.reduce((a, b) =&gt; a + b, 0);
  return { n, ys, hs, errs, sq, sum, mse: Math.round(sum / n * 1000) / 1000 };
}







