유형 E — 여러 건의 교차 엔트로피 평균 [도전]

viewof rG_round = Inputs.button("새 문제", { value: 0, reduce: (v) =&gt; v + 1 })







rG_seed = dojoSeed(dojoSid, 3, "G", rG_round)







rG = {
  const rng = dojoRng(rG_seed);
  const n = 4, ys = [], ps = [], ls = [];
  for (let i = 0; i &lt; n; i++) {
    const y = dojoInt(rng, 0, 1);
    const p = dojoInt(rng, 10, 90) / 100;
    ys.push(y); ps.push(p);
    ls.push(-Math.log(y === 1 ? p : 1 - p));
  }
  const sum = ls.reduce((a, b) =&gt; a + b, 0);
  const worst = ls.indexOf(Math.max(...ls)) + 1;
  return { n, ys, ps, ls, sum, bce: Math.round(sum / n * 1000) / 1000, worst };
}







