도장 사용법




대응 이론: Ch04 학습의 실전 — 학습률, 배치, 역전파, 일반화, 정형 데이터
학번을 입력하면 나만의 문제가 나옵니다. 새 문제 버튼으로 무한 반복 연습.
계산기가 필요합니다. 유형 F·G는 이 수업 손계산의 정점입니다 — 시간을 들여 천천히.
유형은 8개 — [기본] 3 → [응용] 2 → [도전] 3.
훈련 기준: 각 유형에서 연속 3문제 무실수.
// mulberry32 — 문제 번호(시드)가 같으면 항상 같은 문제가 생성된다
dojoRng = function (seed) {
  let a = (seed * 7919 + 104729) &gt;&gt;&gt; 0;
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a &gt;&gt;&gt; 15), 1 | a);
    t = (t + Math.imul(t ^ (t &gt;&gt;&gt; 7), 61 | t)) ^ t;
    return ((t ^ (t &gt;&gt;&gt; 14)) &gt;&gt;&gt; 0) / 4294967296;
  };
}
dojoInt = (rng, lo, hi) =&gt; lo + Math.floor(rng() * (hi - lo + 1))
dojoPick = (rng, arr) =&gt; arr[Math.floor(rng() * arr.length)]
// 정답 비교 — tol 이내면 정답 처리 (학생의 반올림 오차 허용)
dojoOk = (user, answer, tol = 0.005) =&gt;
  user !== null && user !== undefined && Number.isFinite(user) && Math.abs(user - answer) &lt;= tol
dojoMark = (label, ok, answerShown) =&gt; `
  &lt;div style="display:flex;align-items:center;gap:0.5em;padding:0.25em 0;"&gt;
    &lt;span style="font-size:1.1em;"&gt;${ok ? "✅" : "❌"}&lt;/span&gt;
    &lt;span style="font-weight:600;"&gt;${label}&lt;/span&gt;
    &lt;span style="color:${ok ? "#2E7D32" : "#8C1515"};"&gt;
      ${ok ? "정답" : (answerShown != null ? "오답 — 다시 계산해 보세요" : "오답")}
    &lt;/span&gt;
  &lt;/div&gt;`
// 문제 카드
dojoProblem = (title, bodyHtml) =&gt; html`
  &lt;div style="font-family:'Pretendard',sans-serif;border:1.5px solid #8C1515;border-radius:8px;
    overflow:hidden;margin:0.6em 0;max-width:720px;"&gt;
    &lt;div style="background:#8C1515;color:white;padding:0.4em 0.9em;font-weight:700;font-size:0.95em;"&gt;
      ${title}
    &lt;/div&gt;
    &lt;div style="padding:0.7em 0.9em;line-height:1.9;font-size:0.95em;"&gt;${bodyHtml}&lt;/div&gt;
  &lt;/div&gt;`
// 채점 결과 카드
dojoResult = (marks, allOk) =&gt; html`
  &lt;div style="font-family:'Pretendard',sans-serif;border-radius:8px;max-width:720px;margin:0.4em 0;
    padding:0.6em 0.9em;font-size:0.92em;
    background:${allOk ? "#E8F5E9" : "#FFF8E1"};
    border:1.5px solid ${allOk ? "#2E7D32" : "#D4A017"};"&gt;
