    &lt;div style="margin-top:0.35em;font-weight:700;color:${allOk ? "#2E7D32" : "#B8860B"};"&gt;
      ${allOk ? "🎉 전부 정답! 문제 번호를 바꿔 한 번 더 연습해 보세요." : "빨간 항목을 다시 풀어 보세요. 막히면 풀이 보기를 켜세요."}
    &lt;/div&gt;
  &lt;/div&gt;`
// 풀이 카드
dojoSolution = (stepsHtml) =&gt; html`
  &lt;div style="font-family:'Pretendard',sans-serif;border-radius:8px;max-width:720px;margin:0.4em 0;
    padding:0.7em 0.9em;background:#E3F2FD;border:1.5px solid #1565C0;
    line-height:2.0;font-size:0.92em;"&gt;
    &lt;div style="font-weight:700;color:#1565C0;margin-bottom:0.2em;"&gt;풀이&lt;/div&gt;
    ${stepsHtml}
  &lt;/div&gt;`
// FNV-1a — 학번 문자열을 정수로. 사람마다 다른 문제가 나오게 하는 출발점.
dojoHash = function (str) {
  let h = 2166136261 &gt;&gt;&gt; 0;
  const s = String(str);
  for (let i = 0; i &lt; s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 16777619) &gt;&gt;&gt; 0;
  }
  return h &gt;&gt;&gt; 0;
}
// (학번, 주차, 유형, 라운드) → 문제 번호.
// 학번이 다르면 다른 문제, 같은 학번·같은 라운드면 항상 같은 문제(재현 가능).
dojoSeed = function (sid, week, type, round) {
  const key = (sid && String(sid).trim()) ? String(sid).trim() : "guest";
  return (dojoHash(key + "|" + week + "|" + type + "|" + round) % 99999) + 1;
}
// 학번 입력 — 브라우저에 저장되어 모든 도장 페이지에서 유지된다.
