sA = {
  const rng = dojoRng(sA_seed);
  let z = dojoInt(rng, -30, 30) / 10; if (z === 0) z = 0.8;
  const h = 1 / (1 + Math.exp(-z));
  return { z, h: Math.round(h * 1000) / 1000, d: Math.round(h * (1 - h) * 1000) / 1000 };
}







